begin;
create table if not exists class_timetable_application_selections(id uuid primary key default gen_random_uuid(),class_id uuid not null references school_classes(id) on delete cascade,rule_id uuid not null references official_timetable_application_rules(id) on delete restrict,selection_scope text not null default 'PRIMARY' check(selection_scope in('PRIMARY','ADDITIONAL')),subject_choice text,extra_hours smallint,settings jsonb not null default '{}',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(class_id,selection_scope));
create or replace function resolve_iho_application_v1(p_grade smallint,p_code text,p_subject text default null,p_extra smallint default null) returns jsonb language plpgsql stable security definer set search_path=public as $$declare r official_timetable_application_rules; core int;elec int;app int;tot int;allowed text[];begin select * into r from official_timetable_application_rules where code=p_code and active and school_type='IMAM_HATIP_ORTAOKULU';if not found or not(p_grade=any(r.grades)) then raise exception 'Uygulama/sınıf uyumsuz';end if;if p_code='IHO_PARENT_REQUEST_INTENSIVE' then core:=case p_grade when 5 then 30 else 31 end;app:=case p_grade when 5 then 6 else 5 end;elec:=0;allowed:=array['Arapça','Kur’an-ı Kerim','Yabancı Dil'];if p_subject is null or not(p_subject=any(allowed)) then raise exception 'Ders seçimi gerekli';end if;tot:=core+app;elsif p_code='IHO_FOREIGN_STUDENT_TURKISH' then core:=case p_grade when 5 then 30 else 31 end;app:=case p_grade when 5 then 6 else 5 end;elec:=0;p_subject:='Türkçe';tot:=core+app;elsif p_code='IHO_MINISTRY_APPROVED_40' then core:=case p_grade when 5 then 30 else 34 end;app:=case p_grade when 5 then 9 when 6 then 4 when 7 then 4 else 3 end;elec:=case p_grade when 5 then 1 when 6 then 2 when 7 then 2 else 3 end;allowed:=array['Arapça','Yabancı Dil'];if p_subject is null or not(p_subject=any(allowed)) then raise exception 'Ders seçimi gerekli';end if;tot:=40;elsif p_code='IHO_OPTIONAL_ADDITIONAL_ACTIVITY' then core:=36;app:=greatest(0,least(coalesce(p_extra,0),9));elec:=0;tot:=36+app;elsif p_code='IHO_HAFIZLIK' then core:=case p_grade when 8 then 34 else 27 end;app:=0;elec:=case when p_grade=8 then 2 else 0 end;tot:=core+elec;elsif p_code in('IHO_MUSIC','IHO_SPORT') then core:=case when p_code='IHO_MUSIC' then case p_grade when 5 then 31 when 6 then 32 when 7 then 32 else 30 end else case p_grade when 5 then 32 when 6 then 33 when 7 then 33 else 31 end end;app:=case when p_code='IHO_MUSIC' then case p_grade when 5 then 11 when 6 then 10 when 7 then 10 else 11 end else case p_grade when 5 then 10 when 6 then 9 when 7 then 9 else 10 end end;elec:=case when p_grade=8 then 1 else 0 end;tot:=42;else raise exception 'Desteklenmeyen İHO uygulaması';end if;return jsonb_build_object('code',p_code,'grade',p_grade,'base_official_hours',36,'mandatory_core_hours',core,'application_subject',p_subject,'application_hours',app,'general_elective_hours',elec,'actual_weekly_hours',tot,'norm_countable_cap',36,'approval_scope',r.approval_scope,'source_decision_no',r.source_decision_no,'configuration',r.configuration);end$$;
create or replace function get_iho_application_options_v1(p_grade smallint) returns table(code text,label text,selection_scope text,approval_scope text,total_min smallint,total_max smallint,requires_subject boolean,allowed_subjects jsonb,configuration jsonb) language sql stable security definer set search_path=public as $$select 'IHO_STANDARD','Normal İHO','PRIMARY',null::text,36::smallint,36::smallint,false,'[]'::jsonb,'{"base_official_hours":36}'::jsonb union all select r.code,case r.code when 'IHO_PARENT_REQUEST_INTENSIVE' then 'Veli Talebiyle Yoğunlaştırma' when 'IHO_FOREIGN_STUDENT_TURKISH' then 'Yabancı Uyruklu Öğrenciler İçin Türkçe' when 'IHO_MINISTRY_APPROVED_40' then 'Bakanlık Onaylı 40 Saat' when 'IHO_HAFIZLIK' then 'Örgün Eğitimle Birlikte Hafızlık' when 'IHO_MUSIC' then 'Müzik Programı' when 'IHO_SPORT' then 'Spor Programı' when 'IHO_OPTIONAL_ADDITIONAL_ACTIVITY' then 'İlave Eğitici Faaliyet (0-9 Saat)' end,case when r.code='IHO_OPTIONAL_ADDITIONAL_ACTIVITY' then 'ADDITIONAL' else 'PRIMARY' end,r.approval_scope,r.application_total_min,r.application_total_max,r.code in('IHO_PARENT_REQUEST_INTENSIVE','IHO_MINISTRY_APPROVED_40'),coalesce(r.configuration->'subjects','[]'::jsonb),r.configuration from official_timetable_application_rules r where r.active and r.school_type='IMAM_HATIP_ORTAOKULU' and p_grade=any(r.grades)$$;
create or replace function resolve_class_iho_timetable_v1(p_class uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$declare c school_classes;s class_timetable_application_selections;a jsonb;addj jsonb;begin select * into c from school_classes where id=p_class and active;if not found or c.school_type<>'IMAM_HATIP_ORTAOKULU' then raise exception 'Aktif İHO sınıfı bulunamadı';end if;select * into s from class_timetable_application_selections where class_id=p_class and selection_scope='PRIMARY' and active;if found then a:=resolve_iho_application_v1(c.grade_level,(select code from official_timetable_application_rules where id=s.rule_id),s.subject_choice,s.extra_hours)||jsonb_build_object('selection_settings',s.settings);else a:=jsonb_build_object('code','IHO_STANDARD','grade',c.grade_level,'base_official_hours',36,'mandatory_core_hours',(select fixed_hours from official_general_timetable_profiles where active and school_type='IMAM_HATIP_ORTAOKULU' and program_variant='STANDARD' and grade_level=c.grade_level limit 1),'general_elective_hours',(select elective_hours from official_general_timetable_profiles where active and school_type='IMAM_HATIP_ORTAOKULU' and program_variant='STANDARD' and grade_level=c.grade_level limit 1),'actual_weekly_hours',36,'norm_countable_cap',36,'selection_settings','{}'::jsonb);end if;select * into s from class_timetable_application_selections where class_id=p_class and selection_scope='ADDITIONAL' and active;if found then addj:=resolve_iho_application_v1(c.grade_level,(select code from official_timetable_application_rules where id=s.rule_id),s.subject_choice,s.extra_hours)||jsonb_build_object('selection_settings',s.settings);end if;return jsonb_build_object('class_id',p_class,'grade',c.grade_level,'primary',a,'additional',addj);end$$;
create or replace function set_class_iho_application_v1(p_class uuid,p_code text,p_subject text default null,p_extra smallint default null,p_settings jsonb default '{}') returns jsonb language plpgsql security definer set search_path=public as $$declare c school_classes;r official_timetable_application_rules;scope text;resolved jsonb;begin select * into c from school_classes where id=p_class and active;if not found or c.school_type<>'IMAM_HATIP_ORTAOKULU' then raise exception 'Aktif İHO sınıfı bulunamadı';end if;if p_code='IHO_STANDARD' then delete from class_timetable_application_selections where class_id=p_class and selection_scope='PRIMARY';return resolve_class_iho_timetable_v1(p_class);end if;select * into r from official_timetable_application_rules where code=p_code and active;if not found or not(c.grade_level=any(r.grades)) then raise exception 'Uygulama sınıf düzeyiyle uyumsuz';end if;scope:=case when p_code='IHO_OPTIONAL_ADDITIONAL_ACTIVITY' then 'ADDITIONAL' else 'PRIMARY' end;resolved:=resolve_iho_application_v1(c.grade_level,p_code,p_subject,p_extra);insert into class_timetable_application_selections(class_id,rule_id,selection_scope,subject_choice,extra_hours,settings) values(p_class,r.id,scope,p_subject,p_extra,coalesce(p_settings,'{}')) on conflict(class_id,selection_scope) do update set rule_id=excluded.rule_id,subject_choice=excluded.subject_choice,extra_hours=excluded.extra_hours,settings=excluded.settings,active=true,updated_at=now();return resolved||jsonb_build_object('selection_settings',coalesce(p_settings,'{}'));end$$;
update official_timetable_application_rules set configuration=case code when 'IHO_PARENT_REQUEST_INTENSIVE' then '{"article":1,"subjects":["Arapça","Kur’an-ı Kerim","Yabancı Dil"],"grade_rules":{"5":{"mandatory_core":30,"application_max":6,"elective":0},"6":{"mandatory_core":31,"application_max":5,"elective":0},"7":{"mandatory_core":31,"application_max":5,"elective":0}}}'::jsonb when 'IHO_FOREIGN_STUDENT_TURKISH' then '{"article":2,"subject":"Türkçe","grade_rules":{"5":{"mandatory_core":30,"application_hours":6},"6":{"mandatory_core":31,"application_hours":5},"7":{"mandatory_core":31,"application_hours":5}}}'::jsonb when 'IHO_MINISTRY_APPROVED_40' then '{"article":3,"subjects":["Arapça","Yabancı Dil"],"grade_rules":{"5":{"mandatory_core":30,"application_hours":9,"elective":1},"6":{"mandatory_core":34,"application_hours":4,"elective":2},"7":{"mandatory_core":34,"application_hours":4,"elective":2},"8":{"mandatory_core":34,"application_hours":3,"elective":3}}}'::jsonb when 'IHO_HAFIZLIK' then '{"article":4,"grade_rules":{"5":{"fixed":27,"total":27},"6":{"fixed":27,"total":27},"7":{"fixed":27,"total":27},"8":{"fixed":34,"elective":2,"total":36}}}'::jsonb when 'IHO_MUSIC' then '{"article":5,"grade_rules":{"5":{"fixed":31,"program":11,"total":42},"6":{"fixed":32,"program":10,"total":42},"7":{"fixed":32,"program":10,"total":42},"8":{"fixed":30,"elective":1,"program":11,"total":42}}}'::jsonb when 'IHO_SPORT' then '{"article":6,"grade_rules":{"5":{"fixed":32,"program":10,"total":42},"6":{"fixed":33,"program":9,"total":42},"7":{"fixed":33,"program":9,"total":42},"8":{"fixed":31,"elective":1,"program":10,"total":42}}}'::jsonb when 'IHO_OPTIONAL_ADDITIONAL_ACTIVITY' then '{"article":13,"base":36,"max_extra_hours":9,"total_max":45,"examples":["sanat","spor","sosyal-kültürel etkinlik","yabancı dil"]}'::jsonb else configuration end,updated_at=now() where school_type='IMAM_HATIP_ORTAOKULU';
commit;